283	    @ParameterizedTest
284	    @EnumSource(GroupProtocol.class)
285	    public void testAssignedPartitionsMetrics(GroupProtocol groupProtocol) throws InterruptedException {
286	        consumer = newConsumer(groupProtocol, time, mock(KafkaClient.class), subscription,
287	                mock(ConsumerMetadata.class), assignor, false, groupInstanceId);
288	        Metrics metrics = consumer.metricsRegistry();
289	
290	        // This metric is added in the background thread for the AsyncConsumer, so waiting on it to avoid flakiness.
291	        TestUtils.waitForCondition(() -> getMetric(metrics, "assigned-partitions") != null,
292	                "Consumer should register the assigned-partitions metric");
293	        assertNotNull(getMetric(metrics, "assigned-partitions"));
294	        assertEquals(0.0d, getMetric(metrics, "assigned-partitions").metricValue());
295	
296	        subscription.assignFromUser(Set.of(tp0));
297	        assertEquals(1.0d, getMetric(metrics, "assigned-partitions").metricValue());
298	
299	        subscription.assignFromUser(Set.of(tp0, tp1));
300	        assertEquals(2.0d, getMetric(metrics, "assigned-partitions").metricValue());
301	
302	        subscription.unsubscribe();
303	        subscription.subscribe(Set.of(topic), Optional.empty());
304	        subscription.assignFromSubscribed(Set.of(tp0));
305	        assertEquals(1.0d, getMetric(metrics, "assigned-partitions").metricValue());
306	    }
