401	    public void testMetricsRemovedOnClose(GroupProtocol groupProtocol) {
402	        Properties props = new Properties();
403	        props.setProperty(ConsumerConfig.GROUP_PROTOCOL_CONFIG, groupProtocol.name());
404	        props.setProperty(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9999");
405	        consumer = newConsumer(props, new StringDeserializer(), new StringDeserializer());
406	
407	        assertMetricsMap(true);
408	        consumer.close(CloseOptions.timeout(Duration.ZERO));
409	        assertMetricsMap(false);
410	    }
