412	    private void assertMetricsMap(boolean metricsShouldBePresent) {
413	        // Copy the map because we're going to modify it.
414	        Map<MetricName, ? extends Metric> metrics = new HashMap<>(consumer.metrics());
415	
416	        // There's a meta-metric named "count" that is automatically added to the metrics map.
417	        Optional<MetricName> countMetricNameOpt = metrics.keySet().stream()
418	            .filter(metricName -> metricName.name().equals("count") && metricName.group().equals("kafka-metrics-count"))
419	            .findAny();
420	
421	        // Make sure the meta-metric is present and has an entry.
422	        assertTrue(
423	            countMetricNameOpt.isPresent(),
424	            "The \"count\" meta-metric was unexpectedly missing from the Consumer metrics"
425	        );
426	        MetricName countMetricName = countMetricNameOpt.get();
427	        assertNotNull(
428	            metrics.remove(countMetricName),
429	            "The \"count\" meta-metric key was removed from the Consumer metrics map, but it unexpectedly had no entry"
430	        );
431	
432	        if (metricsShouldBePresent) {
433	            assertFalse(
434	                metrics.isEmpty(),
435	                "The consumer should have created metrics, but they are unexpectedly empty"
436	            );
437	        } else {
438	            List<String> expected = List.of();
439	            List<String> actual = metrics.keySet().stream()
440	                .map(metricName -> metricName.group() + ":" + metricName.name())
441	                .sorted()
442	                .collect(Collectors.toList());
443	            assertEquals(
444	                expected,
445	                actual,
446	                "The consumer should have removed its metrics on close(), but there are metrics remaining"
447	            );
448	        }
449	    }
