532	    /*
533	        Create a mock deserializer which throws a SerializationException on the Nth record's value deserialization
534	     */
535	    private StringDeserializer mockErrorDeserializer(int recordNumber) {
536	        int recordIndex = recordNumber - 1;
537	        return new StringDeserializer() {
538	            int i = 0;
539	            @Override
540	            public String deserialize(String topic, byte[] data) {
541	                if (i == recordIndex) {
542	                    throw new SerializationException();
543	                } else {
544	                    i++;
545	                    return super.deserialize(topic, data);
546	                }
547	            }
548	
549	            @Override
550	            public String deserialize(String topic, Headers headers, ByteBuffer data) {
551	                if (i == recordIndex) {
552	                    throw new SerializationException();
553	                } else {
554	                    i++;
555	                    return super.deserialize(topic, headers, data);
556	                }
557	            }
558	        };
559	    }
