172	            log.debug("Initializing the Kafka consumer");
173	            this.requestTimeoutMs = config.getInt(ConsumerConfig.REQUEST_TIMEOUT_MS_CONFIG);
174	            this.defaultApiTimeoutMs = config.getInt(ConsumerConfig.DEFAULT_API_TIMEOUT_MS_CONFIG);
175	            this.time = Time.SYSTEM;
176	            List<MetricsReporter> reporters = CommonClientConfigs.metricsReporters(clientId, config);
177	            this.clientTelemetryReporter = CommonClientConfigs.telemetryReporter(clientId, config);
